124. /// Best-effort join bounded by `deadline`. Returns `true` if the thread finished and was joined,
125. /// `false` if the deadline elapsed first (the thread is left running for process-exit to reclaim).
126. ///
127. /// Shutdown must never block unboundedly on `join()`: a worker wedged in a native/PyO3 bridge call
128. /// would hold the stop past supervisord's `stopwaitsecs` and force a SIGKILL (the M12 crash-loop).
129. /// All worker joins share one absolute `deadline` so the *total* stop wait is bounded by
130. /// [`SHUTDOWN_JOIN_GRACE`], not multiplied per thread.
131. fn join_before(handle: std::thread::JoinHandle<()>, deadline: Instant) -> bool {
132.     loop {
133.         if handle.is_finished() {
134.             let _ = handle.join();
135.             return true;
136.         }
137.         if Instant::now() >= deadline {
138.             return false;
139.         }
140.         std::thread::sleep(Duration::from_millis(20));
141.     }
142. }
