144. /// Decide what [`run`] should do with a `serve()` result. Pure so the lifecycle contract is
145. /// unit-testable without the real PyO3/swss-common bridges (Part B: the Rust-idiom stand-in
146. /// for the reference `signal_handler` / `run` shutdown behaviour).
147. ///
148. /// - A clean shutdown (`Ok(Shutdown)`) or an SFP-system error (`Ok(SfpSystemError)`) means the
149. ///   daemon actually RAN — the process must EXIT (mirroring `DaemonXcvrd.run` returning /
150. ///   `sys.exit`), never loop back into a fresh boot (which is what kept the process alive on
151. ///   `supervisorctl stop` and forced the supervisor SIGKILL crash-loop).
152. /// - A setup `Err` before the daemon came up is retried, so a briefly-unavailable Redis /
153. ///   emulator at boot does not fail the M0 deploy-smoke — UNLESS a shutdown was requested in
154. ///   the meantime, in which case we exit cleanly.
155. #[cfg_attr(test, derive(Debug, PartialEq))]
156. enum RunAction {
157.     Exit(i32),
158.     Retry,
159. }
160. 
161. fn decide_run_action(result: &Result<ServeOutcome, Box<dyn Error>>, shutdown_requested: bool) -> RunAction {
162.     match result {
163.         Ok(ServeOutcome::Shutdown) => RunAction::Exit(0),
164.         Ok(ServeOutcome::SfpSystemError) => RunAction::Exit(SFP_SYSTEM_ERROR),
165.         Err(_) if shutdown_requested => RunAction::Exit(0),
166.         Err(_) => RunAction::Retry,
167.     }
168. }
169. 
170. /// Entry point. Runs the daemon and then EXITS — the reference `DaemonXcvrd.run` blocks on
171. /// `stop_event.wait()`, joins its worker threads, runs `deinit`, and the process exits (0, or
172. /// `SFP_SYSTEM_ERROR`); it does not loop back into a fresh boot. We only retry `serve()` when
173. /// its *setup* fails before the daemon is up (transient Redis/emulator unavailability at boot,
174. /// so the M0 deploy-smoke stays green). Signal handlers are installed up front so a SIGTERM at
175. /// any point — including during a setup-retry sleep — drives a clean exit instead of leaving a
176. /// zombie the supervisor has to SIGKILL.
177. /// Name of the platform flag that starts [`SffManagerTask`] (xcvrd.py forwards it from the
178. /// pmon supervisor command line to the daemon).
179. const ENABLE_SFF_MGR_FLAG: &str = "--enable_sff_mgr";
180. 
181. /// Guarantee the daemon actually runs the SFF (non-CMIS) manager on the injected DUT build.
182. ///
183. /// SONiC starts the SFF-8636 control path only when xcvrd is launched with
184. /// `--enable_sff_mgr` (xcvrd.py:1150 `if self.enable_sff_mgr:`), and pmon's supervisor conf
185. /// sets that flag. But the reversible-injection shim execs this binary with NO argv
186. /// (`os.execv("/usr/local/bin/xcvrd-rs", ["xcvrd-rs"])`), so the flag never reaches us —
187. /// [`SffManagerTask`] would never start, and the SFF-8636 TX_DISABLE (00h:86) / power
188. /// (00h:93) registers stay inert. The e2e SFF gate (`lib/sff8636.py::sff_mgr_enabled`)
189. /// probes the live `/proc/<pid>/cmdline` for the literal `--enable_sff_mgr`, so merely
190. /// defaulting the manager on internally is NOT observable to it — the daemon must genuinely
191. /// carry the flag.
192. ///
193. /// So, if the flag is absent, re-exec ourselves once with it appended. `execv` replaces the
194. /// process image in place (same PID), so pmon's supervisor keeps tracking us as RUNNING, the
195. /// new `/proc/self/cmdline` advertises the flag for the probe, and the existing argv gate in
196. /// [`serve`] then starts [`SffManagerTask`]. The presence check makes this a one-shot (the
197. /// re-exec'd process sees the flag and skips), so there is no exec loop.
198. fn ensure_sff_mgr_flag() {
199.     use std::os::unix::process::CommandExt;
200. 
201.     if std::env::args().any(|a| a == ENABLE_SFF_MGR_FLAG) {
202.         return; // Real Python-style launch already carries it, or this IS the re-exec'd image.
203.     }
204.     let exe = match std::env::current_exe() {
205.         Ok(p) => p,
206.         Err(e) => {
207.             eprintln!(
208.                 "xcvrd-rs: cannot resolve current exe to enable SffManagerTask ({e}); \
209.                  continuing WITHOUT {ENABLE_SFF_MGR_FLAG}"
210.             );
211.             return;
212.         }
213.     };
214.     // Preserve any real argv (the shim passes none) and append the flag.
215.     let mut args: Vec<String> = std::env::args().skip(1).collect();
216.     args.push(ENABLE_SFF_MGR_FLAG.to_string());
217.     eprintln!(
218.         "xcvrd-rs: no {ENABLE_SFF_MGR_FLAG} in argv (injection shim drops it); re-exec {} \
219.          with it so SffManagerTask runs and /proc/cmdline advertises it",
220.         exe.display()
221.     );
222.     // `exec` only returns on failure (otherwise the image is replaced).
223.     let err = std::process::Command::new(&exe).args(&args).exec();
224.     eprintln!(
225.         "xcvrd-rs: re-exec to enable SffManagerTask failed ({err}); continuing WITHOUT \
226.          {ENABLE_SFF_MGR_FLAG}"
227.     );
228. }
229. 
230. pub fn run() -> ! {
231.     // Enable SffManagerTask on the injected DUT build before anything else (must precede
232.     // Python/PyO3 init + thread spawns, since it may re-exec the process image).
233.     ensure_sff_mgr_flag();
234.     eprintln!("xcvrd-rs: starting (M13: SFP insert-event soak; presence, identity, DOM, CMIS, SFF)");
235.     install_signal_handlers();
236.     // Arm the hard shutdown backstop up front so a SIGTERM at ANY point — during boot, the event
237.     // loop, a worker join, or a setup-retry sleep — is guaranteed to exit the process within
238.     // HARD_SHUTDOWN_GRACE, before supervisord escalates to SIGKILL.
239.     spawn_shutdown_enforcer();
240.     loop {
241.         let result = serve();
242.         match decide_run_action(&result, SHUTDOWN_REQUESTED.load(Ordering::SeqCst)) {
243.             RunAction::Exit(0) => {
244.                 eprintln!("xcvrd-rs: graceful shutdown complete; exiting");
245.                 std::process::exit(0);
246.             }
247.             RunAction::Exit(code) => {
248.                 eprintln!("xcvrd-rs: exiting ({code}) for supervisor restart");
249.                 std::process::exit(code);
250.             }
251.             RunAction::Retry => {
252.                 if let Err(e) = &result {
253.                     eprintln!("xcvrd-rs: serve setup error: {e}; retrying in 3s");
254.                 }
255.                 std::thread::sleep(Duration::from_secs(3));
256.             }
257.         }
258.     }
259. }
