     pub fn init(&mut self) -> Result<()> {
         if self.hal.is_none() {
             let hal: Arc<dyn Hal> = Arc::new(BridgeHal::new()?);
             self.hal = Some(hal);
         }
         if self.xcvr_table_helper.is_none() {
             self.xcvr_table_helper = Some(XcvrTableHelper::new(&self.namespaces)?);
         }
